using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketData
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string Category { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

namespace TicketClassifier.Models;

public record TicketRequest(string Subject, string Description, int Priority);

public record PredictionResponse(string Category, Dictionary<string, float> Confidence);

public record EvaluationResponse(
    float MicroAccuracy,
    float MacroAccuracy,
    float LogLoss,
    float LogLossReduction,
    Dictionary<string, PerClassMetrics> PerClass);

public record PerClassMetrics(double Precision, double Recall, double F1Score);

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly IDataView _trainingData;
    private readonly string[] _classLabels;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 42);
        _trainingData = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(_trainingData);
        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);

        // Extract ordered class labels from the key-value mapping
        var labelCol = _trainingData.Schema[nameof(TicketData.Category)];
        var keyCol = _model.GetOutputSchema(_trainingData.Schema)["Label"];
        var keyType = keyCol.Type as Microsoft.ML.Data.KeyDataViewType;

        VBuffer<ReadOnlyMemory<char>> labels = default;
        keyCol.GetKeyValues(ref labels);
        _classLabels = labels.DenseValues().Select(v => v.ToString()).ToArray();
    }

    public PredictionResponse Predict(TicketRequest request)
    {
        var data = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(data);

        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < _classLabels.Length; i++)
        {
            confidence[_classLabels[i]] = prediction.Score.Length > i ? prediction.Score[i] : 0f;
        }

        return new PredictionResponse(prediction.Category, confidence);
    }

    public EvaluationResponse Evaluate()
    {
        var predictions = _model.Transform(_trainingData);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, labelColumnName: "Label");

        var perClass = new Dictionary<string, PerClassMetrics>();
        for (int i = 0; i < metrics.PerClassLogLoss.Count && i < _classLabels.Length; i++)
        {
            perClass[_classLabels[i]] = new PerClassMetrics(
                Precision: metrics.ConfusionMatrix.PerClassPrecision[i],
                Recall: metrics.ConfusionMatrix.PerClassRecall[i],
                F1Score: 2 * metrics.ConfusionMatrix.PerClassPrecision[i] * metrics.ConfusionMatrix.PerClassRecall[i]
                    / (metrics.ConfusionMatrix.PerClassPrecision[i] + metrics.ConfusionMatrix.PerClassRecall[i]
                       + double.Epsilon));
        }

        return new EvaluationResponse(
            MicroAccuracy: (float)metrics.MicroAccuracy,
            MacroAccuracy: (float)metrics.MacroAccuracy,
            LogLoss: (float)metrics.LogLoss,
            LogLossReduction: (float)metrics.LogLossReduction,
            PerClass: perClass);
    }
}

using Microsoft.AspNetCore.Mvc;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketClassifierController : ControllerBase
{
    private readonly TicketClassifierService _classifier;

    public TicketClassifierController(TicketClassifierService classifier)
    {
        _classifier = classifier;
    }

    [HttpPost("predict")]
    public ActionResult<PredictionResponse> Predict([FromBody] TicketRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) || string.IsNullOrWhiteSpace(request.Description))
            return BadRequest("Subject and Description are required.");

        if (request.Priority < 1 || request.Priority > 3)
            return BadRequest("Priority must be between 1 and 3.");

        return Ok(_classifier.Predict(request));
    }

    [HttpGet("evaluate")]
    public ActionResult<EvaluationResponse> Evaluate()
    {
        return Ok(_classifier.Evaluate());
    }
}

